            limit=1 << 24,
        )
    except OSError as exc:
        result.error = f"cannot start {config.binary}: {exc}"
        return result

    stop_reason = ""
    texts: list[str] = []

    async def read_stdout() -> None:
        nonlocal stop_reason
        assert process.stdout is not None
        async for raw in process.stdout:
            session, event = parse_event(raw.decode(errors="replace"), cwd)
            if session and result.session_id is None:
                result.session_id = session
            if event is None:
                continue
            if event.kind == "tool":
                result.tool_calls += 1
                if result.tool_calls > max_tool_calls:
                    result.too_many_calls = True
                    process.kill()
            elif event.kind == "text":
                texts.append(event.text)
            elif event.kind == "step_finish":
                result.tokens += event.tokens
                stop_reason = event.text
            elif event.kind == "error":
                result.error = event.text
            if on_event is not None:
                on_event(event)

    reader = asyncio.create_task(read_stdout())
    stderr = asyncio.create_task(process.stderr.read()) if process.stderr else None
    try:
        await asyncio.wait_for(asyncio.shield(reader), timeout)
        await process.wait()
    except TimeoutError:
        result.timed_out = True
        process.kill()
    except asyncio.CancelledError:
        process.kill()
        raise
    finally:
        with contextlib.suppress(Exception):
            await asyncio.wait_for(process.wait(), 5)
        reader.cancel()
        result.seconds = time.monotonic() - started
        result.text = "".join(texts)

    if stderr is not None and stderr.done() and not result.error:
        result.error = stderr.result().decode(errors="replace")[-300:] if process.returncode else ""
    result.ok = (
        process.returncode == 0 and stop_reason == "stop"
        and not result.timed_out and not result.too_many_calls
    )
    if not result.ok and not result.error and process.returncode:
        result.error = f"opencode exited with {process.returncode}"
    log.info(
        "agent finished ok=%s calls=%d tokens=%d in %.0fs",
        result.ok, result.tool_calls, result.tokens, result.seconds,
    )
    return result
