export type WorldStatus = "queued" | "generating" | "ready" | "failed";

export interface World {
  id: string;
  title: string;
  prompt: string;
  seed: number;
  levels: number[];
  status: WorldStatus;
  storyline: string | null;
  path: string | null;
  running: boolean;
  port: number | null;
  featured: boolean;
  play_count: number;
  /** True when this browser created the world. */
  mine: boolean;
  created_at: string;
  updated_at: string;
}

export interface WorldPage {
  items: World[];
  total: number;
}

export interface WorldEvent {
  id: number;
  step: string;
  state: "started" | "done" | "failed";
  message: string;
  created_at: string;
}

export interface CreateWorld {
  name: string;
  prompt: string;
  seed?: number;
}

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  const response = await fetch(`/api${path}`, {
    headers: { "Content-Type": "application/json" },
    ...init,
  });
  if (!response.ok) {
    throw new Error(`${response.status} ${await response.text()}`);
  }
  return (await response.json()) as T;
}

export const api = {
  listWorlds: ({ q = "", limit = 12 }: { q?: string; limit?: number } = {}) => {
    const params = new URLSearchParams({ limit: String(limit) });
    if (q) params.set("q", q);
    return request<WorldPage>(`/worlds?${params}`);
  },
  getWorld: (id: string) => request<World>(`/worlds/${id}`),
  listEvents: (id: string) => request<WorldEvent[]>(`/worlds/${id}/events`),
  createWorld: (body: CreateWorld) =>
    request<World>("/worlds", { method: "POST", body: JSON.stringify(body) }),
  retryWorld: (id: string) =>
    request<World>(`/worlds/${id}/retry`, { method: "POST" }),
};

/** Display names of the difficulty levels, indexed by level - 1. */
export const LEVEL_NAMES = ["Easy", "Medium", "Hard"];

/** Public link that starts the world on demand and opens it at a level. */
export function playUrl(worldId: string, level: number): string {
  return `/api/play/${worldId}/?level=${level}`;
}
import { type FormEvent, useState } from "react";

import { api, type World } from "../api/client";
import { SHOWCASE } from "../data/showcase";
import { cx } from "./ui";

export interface Draft {
  name: string;
  prompt: string;
}

interface Props {
  draft: Draft;
  onDraftChange: (draft: Draft) => void;
  onCreated: (world: World) => void;
}

const GRID = "var(--color-line)";

export function PromptWindow({ draft, onDraftChange, onCreated }: Props) {
  const { name, prompt } = draft;
  const [seed, setSeed] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const canSubmit =
    name.trim().length >= 2 && prompt.trim().length >= 3 && !busy;
  const activeTheme = SHOWCASE.find((w) => w.prompt === prompt)?.name;

  async function submit(event: FormEvent) {
    event.preventDefault();
    setBusy(true);
    setError(null);
    try {
      const world = await api.createWorld({
        name: name.trim(),
        prompt: prompt.trim(),
        seed: seed === "" ? undefined : Number(seed),
      });
      onCreated(world);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Something went wrong");
    } finally {
      setBusy(false);
    }
  }

  return (
    <section
      aria-labelledby="hero-title"
      className="flex min-h-[min(calc(100svh-4rem),64rem)] flex-col px-5 pt-10 pb-8 sm:px-8 sm:pt-14 lg:px-12"
      style={{
        backgroundImage: `linear-gradient(${GRID} 1px, transparent 1px), linear-gradient(90deg, ${GRID} 1px, transparent 1px)`,
        backgroundSize: "40px 40px",
        backgroundPosition: "-1px -1px",
      }}
    >
      <p className="font-mono text-xs tracking-wide text-muted uppercase">

