        ids[c["name"]] = call("POST", "/worlds", {"name": c["name"] + " " + str(int(time.time()) % 10000), "prompt": c["prompt"], "seed": c["seed"]})["id"]
t0 = time.time()
pending = dict(ids)
while pending:
    time.sleep(4)
    for name, wid in list(pending.items()):
        w = call("GET", "/worlds/" + wid)
        if w["status"] in ("ready", "failed"):
            ev = call("GET", f"/worlds/{wid}/events")
            last = ev[-1]
            print(f"{name:12} {w['status']:7} {time.time()-t0:5.0f}s  {wid}  | {last['step']} {last['message'][:230]!r}", flush=True)
            del pending[name]
EOF
